{
  "name": "扫描采集控制模块",
  "name_en": "DAQ Scan Acquisition Control Module",
  "manufacturer": "",
  "description": "用于实验室自动扫描测量的控制模块，可协调执行器与探测器完成位置扫描、实时绘图、批量扫描以及 HDF5 数据保存，常用于显微成像、光谱映射和多参数测量实验。",
  "description_en": "A laboratory scan-acquisition control module used to coordinate actuators and detectors for automated scans, live plotting, batch runs, and HDF5 data saving. It is commonly used in microscopy, spectral mapping, and multiparameter measurement workflows.",
  "tag_hints": [
    "scan automation",
    "motorized stage control",
    "detector synchronization",
    "live plotting",
    "HDF5 data saving",
    "batch scan",
    "measurement orchestration"
  ],
  "actions": [
    {
      "action_name": "auto-plot_from",
      "description": "选择用于实时绘图的数据来源。",
      "description_en": "Select the data source used for live plotting."
    },
    {
      "action_name": "auto-setup_ui",
      "description": "初始化扫描控制界面。",
      "description_en": "Initialize the scan control user interface."
    },
    {
      "action_name": "auto-set_config",
      "description": "配置扫描模块参数。",
      "description_en": "Configure the scan module settings."
    },
    {
      "action_name": "auto-process_ui_cmds",
      "description": "处理来自界面的控制命令。",
      "description_en": "Process control commands coming from the user interface."
    },
    {
      "action_name": "auto-show_log",
      "description": "打开日志文件。",
      "description_en": "Open the log file."
    },
    {
      "action_name": "auto-quit_fun",
      "description": "退出当前扫描控制实例。",
      "description_en": "Quit the current scan control instance."
    },
    {
      "action_name": "auto-create_dataset_settings",
      "description": "创建数据集和扫描属性设置。",
      "description_en": "Create dataset and scan attribute settings."
    },
    {
      "action_name": "auto-show_batcher",
      "description": "显示批量扫描设置界面。",
      "description_en": "Show the batch scan configuration interface."
    },
    {
      "action_name": "auto-start_scan_batch",
      "description": "开始批量扫描任务。",
      "description_en": "Start a batch scan task."
    },
    {
      "action_name": "auto-loop_scan_batch",
      "description": "循环执行批量扫描。",
      "description_en": "Run the batch scan loop."
    },
    {
      "action_name": "auto-set_scan_batch",
      "description": "配置批量扫描使用的执行器和探测器。",
      "description_en": "Set the actuators and detectors used for batch scanning."
    },
    {
      "action_name": "auto-show_file_attributes",
      "description": "显示扫描或数据集文件属性。",
      "description_en": "Display scan or dataset file attributes."
    },
    {
      "action_name": "auto-show_file_content",
      "description": "显示当前数据文件内容。",
      "description_en": "Show the contents of the current data file."
    },
    {
      "action_name": "auto-show_navigator",
      "description": "打开数据导航器。",
      "description_en": "Open the data navigator."
    },
    {
      "action_name": "auto-show_scan_selector",
      "description": "显示扫描区域选择器。",
      "description_en": "Show the scan region selector."
    },
    {
      "action_name": "auto-load_file",
      "description": "加载数据文件。",
      "description_en": "Load a data file."
    },
    {
      "action_name": "auto-save_file",
      "description": "保存数据文件。",
      "description_en": "Save the data file."
    },
    {
      "action_name": "auto-save_metadata",
      "description": "将元数据写入数据文件。",
      "description_en": "Write metadata into the data file."
    },
    {
      "action_name": "auto-create_new_file",
      "description": "创建新的数据文件。",
      "description_en": "Create a new data file."
    },
    {
      "action_name": "auto-h5saver",
      "description": "获取/设置 HDF5 数据保存器。",
      "description_en": "Get/set the HDF5 data saver."
    },
    {
      "action_name": "auto-close_file",
      "description": "关闭当前数据文件。",
      "description_en": "Close the current data file."
    },
    {
      "action_name": "auto-module_and_data_saver",
      "description": "获取/设置模块与数据保存器。",
      "description_en": "Get/set the module and data saver."
    },
    {
      "action_name": "auto-update_file_settings",
      "description": "更新文件保存设置。",
      "description_en": "Update file saving settings."
    },
    {
      "action_name": "auto-update_scan_info",
      "description": "更新当前扫描信息。",
      "description_en": "Update the current scan information."
    },
    {
      "action_name": "auto-update_actuators",
      "description": "更新参与扫描的执行器列表。",
      "description_en": "Update the list of actuators used in the scan."
    },
    {
      "action_name": "auto-move_to_crosshair",
      "description": "将执行器移动到十字光标位置。",
      "description_en": "Move the actuators to the crosshair position."
    },
    {
      "action_name": "auto-move_at",
      "description": "将执行器移动到指定坐标。",
      "description_en": "Move the actuators to the specified coordinates."
    },
    {
      "action_name": "auto-value_changed",
      "description": "响应参数值变化。",
      "description_en": "Handle a parameter value change."
    },
    {
      "action_name": "auto-clear_plot_from",
      "description": "清除实时绘图数据来源设置。",
      "description_en": "Clear the live plot data source selection."
    },
    {
      "action_name": "auto-check_number_type_viewers",
      "description": "检查实时显示所需查看器的数量和类型。",
      "description_en": "Check the number and types of viewers needed for live display."
    },
    {
      "action_name": "auto-prepare_viewers",
      "description": "准备实时显示查看器。",
      "description_en": "Prepare the viewers for live display."
    },
    {
      "action_name": "auto-update_status",
      "description": "更新状态信息。",
      "description_en": "Update the status message."
    },
    {
      "action_name": "auto-thread_status",
      "description": "处理采集线程返回的状态信息。",
      "description_en": "Handle status information returned by the acquisition thread."
    },
    {
      "action_name": "auto-save_temp_live_data",
      "description": "暂存实时扫描数据。",
      "description_en": "Temporarily store live scan data."
    },
    {
      "action_name": "auto-update_live_plots",
      "description": "更新实时图形显示。",
      "description_en": "Update the live plot display."
    },
    {
      "action_name": "auto-set_scan",
      "description": "配置当前扫描任务。",
      "description_en": "Configure the current scan."
    },
    {
      "action_name": "auto-set_metadata_about_current_scan",
      "description": "设置当前扫描的元数据。",
      "description_en": "Set metadata for the current scan."
    },
    {
      "action_name": "auto-set_metadata_about_dataset",
      "description": "设置数据集元数据。",
      "description_en": "Set dataset metadata."
    },
    {
      "action_name": "auto-exit_runner_thread",
      "description": "安全退出扫描执行线程。",
      "description_en": "Safely exit the scan runner thread."
    },
    {
      "action_name": "auto-start_scan",
      "description": "开始扫描采集。",
      "description_en": "Start scan acquisition."
    },
    {
      "action_name": "auto-set_ini_positions",
      "description": "设置扫描初始位置。",
      "description_en": "Set the initial scan positions."
    },
    {
      "action_name": "auto-stop_scan",
      "description": "停止扫描采集。",
      "description_en": "Stop scan acquisition."
    },
    {
      "action_name": "auto-do_scan",
      "description": "以编程方式执行扫描。",
      "description_en": "Run a scan programmatically."
    }
  ]
}

